  <script>
    const $ = (sel, root = document) => root.querySelector(sel);
    const $$ = (sel, root = document) => Array.from(root.querySelectorAll(sel));

    const els = {
      keyword: $("#keyword"),
      audience: $("#audience"),
      angle: $("#angle"),
      competitors: $("#competitors"),
      brandNotes: $("#brandNotes"),
      gapCards: $("#gapCards"),
      outlineCards: $("#outlineCards"),
      metaCards: $("#metaCards"),
      faqCards: $("#faqCards"),
      claimCards: $("#claimCards"),
      briefOutput: $("#briefOutput"),
      gapCount: $("#gapCount"),
      briefScore: $("#briefScore"),
      riskCount: $("#riskCount"),
      toast: $("#toast")
    };

    const STORAGE_KEY = "seoGapBriefBuilder.v1";

    let state = {
      inputs: {
        keyword: "",
        audience: "",
        angle: "",
        competitors: "",
        brandNotes: ""
      },
      gaps: [],
      outline: [],
      meta: [],
      faqs: [],
      claims: []
    };

    const templates = {
      gaps: () => ({
        type: "Opportunity",
        title: "New gap card",
        body: "Describe the missing angle, weak competitor coverage, or user need.",
        priority: "Medium"
      }),
      outline: () => ({
        type: "Section",
        title: "New outline section",
        body: "Add notes, bullets, examples, internal links, or proof needed.",
        priority: "Medium"
      }),
      meta: () => ({
        type: "Metadata",
        title: "New title option",
        body: "Meta description option goes here.",
        priority: "Medium"
      }),
      faqs: () => ({
        type: "FAQ",
        title: "New question?",
        body: "Draft the answer angle or source needed.",
        priority: "Medium"
      }),
      claims: () => ({
        type: "Verify",
        title: "Claim to check",
        body: "Source, evidence, date, and wording notes.",
        checked: false,
        priority: "Medium"
      })
    };

    function uid() {
      return Math.random().toString(36).slice(2, 10);
    }

    function cleanText(text) {
      return String(text || "")
        .replace(/\r/g, "")
        .replace(/\t/g, " ")
        .replace(/[ ]{2,}/g, " ")
        .trim();
    }

    function splitLines(text) {
      return cleanText(text)
        .split(/\n|•|\u2022|\- /)
        .map(s => s.replace(/^[-*#\d.)\s]+/, "").trim())
        .filter(Boolean);
    }

    function words(text) {
      return cleanText(text)
        .toLowerCase()
        .replace(/[^a-z0-9\s-]/g, " ")
        .split(/\s+/)
        .filter(w => w.length > 2);
    }

    function titleCase(text) {
      return cleanText(text)
        .split(" ")
        .map(w => w ? w[0].toUpperCase() + w.slice(1) : "")
        .join(" ");
    }

    function unique(arr) {
      const seen = new Set();
      return arr.filter(item => {
        const key = cleanText(typeof item === "string" ? item : item.title + item.body).toLowerCase();
        if (!key || seen.has(key)) return false;
        seen.add(key);
        return true;
      });
    }

    function topTerms(text, limit = 8) {
      const stop = new Set([
        "the","and","for","with","that","this","from","into","your","you","are","can","how",
        "why","what","when","where","best","guide","tips","about","have","has","had","not",
        "but","all","our","their","they","them","then","than","was","were","been","being",
        "will","would","should","could","use","using","article","content","page","pages"
      ]);
      const counts = {};
      words(text).forEach(w => {
        if (!stop.has(w)) counts[w] = (counts[w] || 0) + 1;
      });
      return Object.entries(counts)
        .sort((a,b) => b[1] - a[1])
        .slice(0, limit)
        .map(([w]) => w);
    }

    function inferIntent(keyword, angle, notes) {
      const text = `${keyword} ${angle} ${notes}`.toLowerCase();
      if (/price|cost|fee|rate|cheap|affordable|pricing/.test(text)) return "Cost comparison";
      if (/best|top|review|compare|vs|alternative/.test(text)) return "Comparison";
      if (/how to|step|setup|build|create|fix/.test(text)) return "How-to";
      if (/what is|definition|meaning|basics|beginner/.test(text)) return "Explainer";
      if (/near me|local|city|area/.test(text)) return "Local";
      return "Decision support";
    }

    function makeCards(items, fallbackType) {
      return items.map(item => ({
        id: uid(),
        type: item.type || fallbackType,
        title: item.title || "Untitled",
        body: item.body || "",
        priority: item.priority || "Medium",
        checked: item.checked || false
      }));
    }

    function generate() {
      syncInputsToState();

      const keyword = cleanText(state.inputs.keyword) || "target keyword";
      const audience = cleanText(state.inputs.audience) || "target audience";
      const angle = cleanText(state.inputs.angle);
      const competitorNotes = cleanText(state.inputs.competitors);
      const brandNotes = cleanText(state.inputs.brandNotes);
      const allNotes = `${angle}\n${competitorNotes}\n${brandNotes}`;
      const terms = topTerms(allNotes + " " + keyword, 10);
      const lines = splitLines(competitorNotes);
      const intent = inferIntent(keyword, angle, competitorNotes);

      const lineCards = lines.slice(0, 8).map((line, i) => ({
        type: i < 3 ? "SERP gap" : "Competitor note",
        title: line.length > 62 ? line.slice(0, 62).trim() + "…" : line,
        body: `Turn this into a useful section by adding an original example, clearer answer, stronger evidence, or better comparison for ${audience}.`,
        priority: i < 3 ? "High" : "Medium"
      }));

      const termCards = terms.slice(0, 5).map(term => ({
        type: "Missing subtopic",
        title: `${titleCase(term)} angle`,
        body: `Check whether competitors cover this deeply. Add definitions, examples, mistakes, decision criteria, and source-backed claims where useful.`,
        priority: "Medium"
      }));

      state.gaps = makeCards(unique([
        {
          type: "Search intent",
          title: `${intent} intent for “${keyword}”`,
          body: `The page should satisfy ${audience} by matching the real job behind the query, not just repeating the keyword. Use the angle: ${angle || "clarify the decision, tradeoffs, and next step."}`,
          priority: "High"
        },
        {
          type: "Differentiator",
          title: "What this article should do better",
          body: `Add practical judgment, examples, checklists, and source discipline where competitor pages are thin, generic, outdated, or too broad.`,
          priority: "High"
        },
        ...lineCards,
        ...termCards,
        {
          type: "Reader objection",
          title: "Objections and edge cases",
          body: `Add a section for when the usual advice does not apply, especially for ${audience}. Include warning signs and decision rules.`,
          priority: "High"
        }
      ]), "Opportunity");

      state.outline = makeCards([
        {
          type: "H1",
          title: `${titleCase(keyword)}: Practical Guide for ${audience}`,
          body: "Open with a direct answer, define who the advice is for, and state the main tradeoff.",
          priority: "High"
        },
        {
          type: "H2",
          title: `What ${keyword} really means`,
          body: "Give a plain definition, explain why people search it, and clarify common misunderstandings.",
          priority: "High"
        },
        {
          type: "H2",
          title: "Decision factors",
          body: `List the criteria ${audience} should use before acting. Include costs, timing, risk, effort, alternatives, and proof needed.`,
          priority: "High"
        },
        {
          type: "H2",
          title: "Competitor gaps to beat",
          body: state.gaps.slice(0, 5).map(g => `• ${g.title}`).join("\n"),
          priority: "High"
        },
        {
          type: "H2",
          title: "Examples and scenarios",
          body: "Add 2-3 realistic examples that show when the advice works, when it fails, and what changes the answer.",
          priority: "Medium"
        },
        {
          type: "H2",
          title: "Mistakes to avoid",
          body: "Turn weak competitor coverage into a practical warning section.",
          priority: "Medium"
        },
        {
          type: "H2",
          title: "FAQ",
          body: "Answer common questions directly in 40-80 words each.",
          priority: "Medium"
        },
        {
          type: "CTA",
          title: "Next step",
          body: brandNotes || "Give the reader a useful next step without over-selling.",
          priority: "Medium"
        }
      ], "Section");

      state.meta = makeCards([
        {
          type: "Title",
          title: `${titleCase(keyword)}: What to Know Before You Decide`,
          body: `A practical guide for ${audience} covering tradeoffs, mistakes, examples, and when the usual advice does not apply.`,
          priority: "High"
        },
        {
          type: "Title",
          title: `${titleCase(keyword)} Guide for ${titleCase(audience)}`,
          body: `Learn how to evaluate ${keyword}, compare your options, avoid weak advice, and build a clearer next-step plan.`,
          priority: "Medium"
        },
        {
          type: "Title",
          title: `${titleCase(keyword)}: Pros, Cons, Examples, and Mistakes`,
          body: `Use this decision-focused guide to understand the main benefits, risks, competitor gaps, and practical checks before acting.`,
          priority: "Medium"
        },
        {
          type: "Title",
          title: `Is ${titleCase(keyword)} Worth It?`,
          body: `See when ${keyword} makes sense, when it can backfire, and what ${audience} should verify first.`,
          priority: "Medium"
        }
      ], "Metadata");

      const faqSeeds = [
        `What is ${keyword}?`,
        `Who should consider ${keyword}?`,
        `What are the biggest mistakes with ${keyword}?`,
        `How do you compare ${keyword} options?`,
        `When is ${keyword} not worth it?`,
        `What should ${audience} verify first?`
      ];

      const noteQuestions = lines
        .filter(l => /\?/.test(l) || /how|what|why|when|best|cost|compare/i.test(l))
        .slice(0, 4)
        .map(l => l.endsWith("?") ? l : `${l}?`);

      state.faqs = makeCards(unique([...noteQuestions, ...faqSeeds]).slice(0, 10).map(q => ({
        type: "FAQ",
        title: q,
        body: "Answer directly, then add one practical qualifier or example. Verify any factual, legal, medical, financial, pricing, or statistics-based statement.",
        priority: /mistake|not worth|verify|cost|compare/i.test(q) ? "High" : "Medium"
      })), "FAQ");

      state.claims = makeCards([
        {
          type: "Evidence",
          title: "Define source requirements",
          body: "List the sources needed for statistics, rules, dates, pricing, product claims, legal/tax/medical statements, and competitor comparisons.",
          priority: "High"
        },
        {
          type: "Freshness",
          title: "Check dates and current rules",
          body: "Verify anything that may have changed recently, including rates, thresholds, regulations, feature sets, rankings, and market data.",
          priority: "High"
        },
        {
          type: "Comparison",
          title: "Support every competitor claim",
          body: "Avoid saying competitors miss something unless notes or examples clearly support it.",
          priority: "High"
        },
        {
          type: "Reader safety",
          title: "Add limits and exceptions",
          body: `Flag where advice depends on the reader’s situation, especially for ${audience}.`,
          priority: "High"
        },
        {
          type: "E-E-A-T",
          title: "Add proof of usefulness",
          body: "Include examples, methodology, author review notes, citations, screenshots, templates, or firsthand testing where possible.",
          priority: "Medium"
        },
        {
          type: "CTA",
          title: "Avoid unsupported promises",
          body: "Make the CTA useful and specific without guaranteeing outcomes.",
          priority: "Medium"
        }
      ], "Verify");

      renderAll();
      save();
      toast("Cards generated");
    }

    function syncInputsToState() {
      state.inputs.keyword = els.keyword.value;
      state.inputs.audience = els.audience.value;
      state.inputs.angle = els.angle.value;
      state.inputs.competitors = els.competitors.value;
      state.inputs.brandNotes = els.brandNotes.value;
    }

    function syncStateToInputs() {
      els.keyword.value = state.inputs.keyword || "";
      els.audience.value = state.inputs.audience || "";
      els.angle.value = state.inputs.angle || "";
      els.competitors.value = state.inputs.competitors || "";
      els.brandNotes.value = state.inputs.brandNotes || "";
    }

    function cardHtml(item, bucket) {
      const isClaim = bucket === "claims";
      const lengthNote = bucket === "meta"
        ? `<div class="mini">Title ${item.title.length} chars · Meta ${item.body.length} chars</div>`
        : "";

      return `
        <article class="card" data-id="${item.id}" data-bucket="${bucket}">
          <div class="card-top">
            <span class="badge ${badgeClass(item.priority)}">${escapeHtml(item.type || "Card")}</span>
            <div class="row tight no-print">
              ${isClaim ? `<button class="small secondary" data-check="${item.id}">${item.checked ? "Done" : "Open"}</button>` : ""}
              <button class="small danger" data-delete="${item.id}">Delete</button>
            </div>
          </div>

          ${isClaim ? `
            <div class="check">
              <div class="box" data-check="${item.id}" data-checked="${item.checked ? "true" : "false"}">${item.checked ? "✓" : ""}</div>
              <div>
                <div class="editable" contenteditable="true" data-field="title">${escapeHtml(item.title)}</div>
                <div class="editable mini" contenteditable="true" data-field="body">${escapeHtml(item.body)}</div>
              </div>
            </div>
          ` : `
            <div class="editable" contenteditable="true" data-field="title">${escapeHtml(item.title)}</div>
            <div class="editable mini" contenteditable="true" data-field="body">${escapeHtml(item.body)}</div>
          `}

          ${lengthNote}

          <div class="chipline no-print" aria-label="Priority">
            ${["High","Medium","Low"].map(p => `<span class="chip" data-priority="${p}" data-on="${item.priority === p ? "true" : "false"}">${p}</span>`).join("")}
          </div>
        </article>
      `;
    }

    function badgeClass(priority) {
      if (priority === "High") return "bad";
      if (priority === "Low") return "good";
      return "warn";
    }

    function escapeHtml(str) {
      return String(str || "")
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;");
    }

    function renderBucket(bucket, el) {
      const arr = state[bucket] || [];
      el.innerHTML = arr.length
        ? arr.map(item => cardHtml(item, bucket)).join("")
        : `<div class="card"><p class="hint">No cards yet. Generate cards or tap Add.</p></div>`;
    }

    function renderAll() {
      syncStateToInputs();
      renderBucket("gaps", els.gapCards);
      renderBucket("outline", els.outlineCards);
      renderBucket("meta", els.metaCards);
      renderBucket("faqs", els.faqCards);
      renderBucket("claims", els.claimCards);
      renderBrief();
      updateStats();
    }

    function renderBrief() {
      syncInputsToState();

      const keyword = cleanText(state.inputs.keyword) || "[primary keyword]";
      const audience = cleanText(state.inputs.audience) || "[audience]";
      const angle = cleanText(state.inputs.angle) || "[angle]";
      const brandNotes = cleanText(state.inputs.brandNotes) || "[internal notes]";
      const competitors = cleanText(state.inputs.competitors) || "[competitor notes]";

      const high = arr => arr.filter(x => x.priority === "High");
      const list = arr => arr.map(x => `- ${x.title}${x.body ? "\n  ${x.body}".replace("${x.body}", x.body.replace(/\n/g, "\n  ")) : ""}`).join("\n");
      const metaList = state.meta.map(x => `- Title: ${x.title}\n  Meta: ${x.body}`).join("\n");
      const claimList = state.claims.map(x => `- [${x.checked ? "x" : " "}] ${x.title}\n  ${x.body}`).join("\n");

      const brief =
`SEO CONTENT BRIEF

Primary keyword
${keyword}

Audience
${audience}

Content angle
${angle}

Search intent target
${inferIntent(keyword, angle, competitors)}

Competitor notes
${competitors}

Internal notes
${brandNotes}

Highest-priority gaps
${list(high(state.gaps).length ? high(state.gaps) : state.gaps.slice(0, 5))}

Recommended outline
${list(state.outline)}

Title and meta options
${metaList}

FAQ prompts
${list(state.faqs)}

Claims and verification checklist
${claimList}

Drafting instructions
- Lead with a direct answer.
- Cover the query fully without padding.
- Beat generic competitor pages with examples, decision rules, edge cases, and proof.
- Verify current facts before publishing.
- Add internal links where they genuinely help the reader.
- Keep metadata specific to the audience and angle.`;

      els.briefOutput.textContent = brief;
    }

    function updateStats() {
      const gaps = state.gaps.length;
      const sections = state.outline.length + state.meta.length + state.faqs.length;
      const uncheckedClaims = state.claims.filter(c => !c.checked).length;
      const score = Math.min(100, gaps * 7 + sections * 4 + state.claims.filter(c => c.checked).length * 3);

      els.gapCount.textContent = gaps;
      els.briefScore.textContent = score;
      els.riskCount.textContent = uncheckedClaims;
    }

    function addCard(bucket) {
      const item = templates[bucket]();
      item.id = uid();
      state[bucket].push(item);
      renderAll();
      save();
      toast("Card added");
    }

    function deleteCard(id) {
      for (const bucket of ["gaps","outline","meta","faqs","claims"]) {
        const before = state[bucket].length;
        state[bucket] = state[bucket].filter(item => item.id !== id);
        if (state[bucket].length !== before) break;
      }
      renderAll();
      save();
    }

    function updateCardFromDom(card) {
      const id = card.dataset.id;
      const bucket = card.dataset.bucket;
      const item = state[bucket].find(x => x.id === id);
      if (!item) return;

      const title = $('[data-field="title"]', card);
      const body = $('[data-field="body"]', card);

      item.title = cleanText(title ? title.innerText : item.title);
      item.body = cleanText(body ? body.innerText : item.body);
      renderBrief();
      updateStats();
      save();
    }

    function setPriority(card, priority) {
      const id = card.dataset.id;
      const bucket = card.dataset.bucket;
      const item = state[bucket].find(x => x.id === id);
      if (!item) return;
      item.priority = priority;
      renderAll();
      save();
    }

    function toggleClaim(id) {
      const item = state.claims.find(x => x.id === id);
      if (!item) return;
      item.checked = !item.checked;
      renderAll();
      save();
    }

    function save() {
      syncInputsToState();
      localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
    }

    function load() {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (!raw) return;
      try {
        const parsed = JSON.parse(raw);
        state = {
          inputs: { ...state.inputs, ...(parsed.inputs || {}) },
          gaps: parsed.gaps || [],
          outline: parsed.outline || [],
          meta: parsed.meta || [],
          faqs: parsed.faqs || [],
          claims: parsed.claims || []
        };
        renderAll();
      } catch {
        localStorage.removeItem(STORAGE_KEY);
      }
    }

    function clearAll() {
      if (!confirm("Clear all inputs and cards?")) return;
      state = {
        inputs: { keyword: "", audience: "", angle: "", competitors: "", brandNotes: "" },
        gaps: [],
        outline: [],
        meta: [],
        faqs: [],
        claims: []
      };
      localStorage.removeItem(STORAGE_KEY);
      renderAll();
      toast("Cleared");
    }

    async function copyText(text) {
      try {
        await navigator.clipboard.writeText(text);
        toast("Copied");
      } catch {
        const area = document.createElement("textarea");
        area.value = text;
        document.body.appendChild(area);
        area.select();
        document.execCommand("copy");
        area.remove();
        toast("Copied");
      }
    }

    function download(filename, text, type = "text/plain") {
      const blob = new Blob([text], { type });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = filename;
      a.click();
      URL.revokeObjectURL(url);
    }

    function toast(msg) {
      els.toast.textContent = msg;
      els.toast.classList.add("show");
      clearTimeout(toast._t);
      toast._t = setTimeout(() => els.toast.classList.remove("show"), 1500);
    }

    function loadSample() {
      state.inputs = {
        keyword: "best Roth conversion strategy",
        audience: "pre-retirees with $1M-$3M invested",
        angle: "Explain when Roth conversions are worth it, when they backfire, and how to avoid tax bracket and Medicare premium surprises.",
        competitors:
`Top pages define Roth conversions but stay generic
Few examples show partial conversions over multiple years
Competitors mention tax brackets but not IRMAA clearly
Little guidance on widow/widower tax risk
Almost no checklist for source documents
Some pages overpromise tax-free growth without explaining tradeoffs
People Also Ask: Is a Roth conversion worth it after age 60?
People Also Ask: How much tax will I pay on a Roth conversion?`,
        brandNotes:
`Mention that individual tax advice depends on full tax return, income, deductions, IRMAA exposure, state taxes, estate goals, and time horizon.
Preferred CTA: ask for a tax-aware retirement income review.`
      };
      generate();
    }

    function exportJson() {
      save();
      download("seo-gap-brief-builder-backup.json", JSON.stringify(state, null, 2), "application/json");
      toast("JSON exported");
    }

    function importJson(file) {
      const reader = new FileReader();
      reader.onload = () => {
        try {
          const imported = JSON.parse(reader.result);
          state = {
            inputs: { ...state.inputs, ...(imported.inputs || {}) },
            gaps: imported.gaps || [],
            outline: imported.outline || [],
            meta: imported.meta || [],
            faqs: imported.faqs || [],
            claims: imported.claims || []
          };
          renderAll();
          save();
          toast("JSON imported");
        } catch {
          toast("Import failed");
        }
      };
      reader.readAsText(file);
    }

    document.addEventListener("input", e => {
      if (["keyword","audience","angle","competitors","brandNotes"].includes(e.target.id)) {
        save();
        renderBrief();
        updateStats();
        return;
      }

      const card = e.target.closest(".card");
      if (card && e.target.matches("[contenteditable='true']")) {
        updateCardFromDom(card);
      }
    });

    document.addEventListener("click", e => {
      const add = e.target.closest("[data-add]");
      if (add) {
        addCard(add.dataset.add);
        return;
      }

      const del = e.target.closest("[data-delete]");
      if (del) {
        deleteCard(del.dataset.delete);
        return;
      }

      const chip = e.target.closest("[data-priority]");
      if (chip) {
        const card = chip.closest(".card");
        setPriority(card, chip.dataset.priority);
        return;
      }

      const check = e.target.closest("[data-check]");
      if (check) {
        toggleClaim(check.dataset.check);
      }
    });

    $("#generateBtn").addEventListener("click", generate);
    $("#sampleBtn").addEventListener("click", loadSample);
    $("#clearBtn").addEventListener("click", clearAll);

    $("#refreshBriefBtn").addEventListener("click", () => {
      renderBrief();
      save();
      toast("Brief refreshed");
    });

    $("#copyBriefBtn").addEventListener("click", () => {
      renderBrief();
      copyText(els.briefOutput.textContent);
    });

    $("#downloadBtn").addEventListener("click", () => {
      renderBrief();
      const safe = (cleanText(state.inputs.keyword) || "seo-brief")
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, "-")
        .replace(/^-|-$/g, "");
      download(`${safe}-content-brief.txt`, els.briefOutput.textContent);
    });

    $("#printBtn").addEventListener("click", () => {
      renderBrief();
      window.print();
    });

    $("#exportJsonBtn").addEventListener("click", exportJson);
    $("#importJsonBtn").addEventListener("click", () => $("#importFile").click());
    $("#importFile").addEventListener("change", e => {
      const file = e.target.files && e.target.files[0];
      if (file) importJson(file);
      e.target.value = "";
    });

    window.addEventListener("beforeunload", save);

    load();
    renderAll();
  </script>
</body>
</html>
